\begin{align*}
x &= \frac{1}{4 \log_{27} 3}\\
x &= \frac{1}{4 \frac{\log_{10} 3}{\log_{10} 27}}\\
x &= \frac{\log_{10} 27}{4 \log_{10} 3}\\
x &= \boxed{\frac{3}{4}}
\end{align*}

